<?php
namespace Database\Seeders;
use App\Models\{Page,Setting};use Illuminate\Database\Seeder;
class EducationContentSeeder extends Seeder{
 public function run():void{
  Setting::updateOrCreate(['key'=>'education_model'],['value'=>'Дополнительные предпрофессиональные общеобразовательные программы в области искусств','group'=>'education','label'=>'Основной тип образовательных программ']);
  $this->page('educational-programs','Образовательные программы','<p>Школа реализует дополнительные предпрофессиональные общеобразовательные программы в области музыкального искусства. По опубликованным сведениям учреждения обучение ведётся по 17 инструментальным и 5 вокально-хоровым программам.</p><p>Актуальный перечень программ, сроки обучения, возраст поступающих и файлы образовательных программ публикуются в каталоге образовательных программ.</p>');
  $this->page('admission-rules','Правила приёма','<p>Приём на дополнительные предпрофессиональные программы в области искусств проводится с учётом творческих способностей и физических данных поступающих, необходимых для освоения соответствующей программы.</p><p>Порядок приёма регулируется законодательством Российской Федерации и локальными актами школы. Актуальные сроки, требования, формы заявлений, график вступительных испытаний и результаты публикуются в разделе «Поступление».</p><p><strong>Важно:</strong> перед подачей документов используйте только материалы текущей приёмной кампании.</p>');
  $this->page('official-education','Образование','<p>Образовательная деятельность школы осуществляется по дополнительным предпрофессиональным общеобразовательным программам в области искусств. В каталоге программ размещаются описание, срок обучения, возраст поступления, условия приёма и утверждённые файлы программ.</p>');
 }
 private function page(string $slug,string $title,string $content):void{Page::where('slug',$slug)->update(['title'=>$title,'content'=>$content,'excerpt'=>strip_tags(str($content)->limit(180)),'is_published'=>true]);}
}